import io
import runpy
import sys
import unittest
from unittest.mock import patch

DESIRED = "Invalid input\nMaximum is 10\nMinimum is 2"
DESIRED2 = None
STDIN = "7\n2\nbob\n10\n4\ndone\n"


def run_student(stdin=STDIN):
    output = io.StringIO()
    with patch('builtins.input', side_effect=_input_side_effect(stdin)):
        with patch('sys.stdout', output):
            try:
                runpy.run_path('student.py', run_name='__main__')
            except SystemExit:
                pass
    return output.getvalue()


def _input_side_effect(stdin):
    lines = stdin.splitlines()
    # Preserve trailing blank semantics for programs that call input() once per line
    if stdin.endswith('\n'):
        # splitlines drops final empty; reconstruct queue of lines without newlines
        pass
    queue = list(lines)

    def _input(prompt=''):
        if not queue:
            raise EOFError('EOF when reading a line')
        return queue.pop(0)

    return _input


class OutputTests(unittest.TestCase):
    def test_desired_output(self):
        got = run_student().rstrip()
        # Normalize trailing whitespace per line for friendlier comparison
        got_norm = '\n'.join(line.rstrip() for line in got.splitlines()).rstrip()
        want = DESIRED.rstrip() if isinstance(DESIRED, str) else DESIRED
        alts = [want]
        if DESIRED2:
            alts.append(DESIRED2.rstrip())
        if got_norm not in alts:
            self.assertEqual(got_norm, want)


class SourceTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open('student.py', encoding='utf-8') as f:
            cls.src = f.read()

    def test_source_input(self):
        self.assertIn("input", self.src,
            "You must prompt for the numbers using the input() function.")

    def test_source_print(self):
        self.assertIn("print", self.src,
            "You must use the print function to print the output.")

    def test_source_while(self):
        self.assertIn("while", self.src,
            "You should use a while statement to read the numbers.")

    def test_source_int(self):
        self.assertIn("int", self.src,
            "You should use the int() function to convert from a string to an integer.")

    def test_source_not_2(self):
        self.assertNotIn(" 2", self.src,
            "You should actually compute the maximum and minimum.")

    def test_source_not_2_2(self):
        self.assertNotIn("=2", self.src,
            "You should actually compute the maximum and minimum.")

    def test_source_not_10(self):
        self.assertNotIn(" 10", self.src,
            "You should actually compute the maximum and minimum.")

    def test_source_not_10_2(self):
        self.assertNotIn("=10", self.src,
            "You should actually compute the maximum and minimum.")

    def test_source_try(self):
        self.assertIn("try", self.src,
            "You should handle bad numbers using a try/except structure.")

    def test_source_except(self):
        self.assertIn("except", self.src,
            "You should handle bad numbers using a try/except structure.")
